<section class="card"><div class="section-heading"><h2>Histórico de correções</h2><x-icon name="clock" /></div><p class="muted small">Cada correção permanece registrada, com a data, o responsável e as pontuações daquela revisão.</p>@foreach($attempt->grades as $grade)<details class="grade-revision"><summary><span>Revisão {{ $grade->revision }} · {{ $grade->kind==='final'?'Nota final':'Pontuação provisória' }}</span><b>{{ number_format($grade->grade,2,',','.') }} / 10</b></summary><p>{{ $grade->created_at->format('d/m/Y H:i') }} · {{ $grade->reviewer?->name ?? 'Correção automática' }}</p><p>{{ $grade->reason }}</p><div class="table-wrap"><table><thead><tr><th>Item</th><th>Resposta registrada</th><th>Pontos</th><th>Observação</th></tr></thead><tbody>@foreach($grade->answer_snapshot as $row)<tr><td>{{ $row['question_code'] }}</td><td>{{ $row['answer'] }}</td><td>{{ $row['points']??'Pendente' }}</td><td>{{ $row['feedback']??'—' }}</td></tr>@endforeach</tbody></table></div></details>@endforeach</section>
